def digest(value):
    return hashlib.sha256(value).hexdigest()


def read_original(directory,record):
    path=(directory/record["name"]).resolve()
    if path.stat().st_size!=record["bytes"]:
        raise ValueError("Whole source size changed: "+str(path))
    raw=path.read_bytes()
    if digest(raw)!=record["sha256"]:
        raise ValueError("Whole source SHA changed: "+str(path))
    return raw.decode("utf-8")


def transform(value,changes,*,reverse=False):
    for change in reversed(changes):
        start=change["start_new" if reverse else "start_original"]
        end=change["end_new" if reverse else "end_original"]
        before=change["new" if reverse else "old"]
        after=change["old" if reverse else "new"]
        if value[start:end]!=before:
            raise ValueError("An exact complete source span changed")
        value=value[:start]+after+value[end:]
    return value


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument("--source-directory",type=Path,required=True)
    p.add_argument("--output-directory",type=Path,required=True)
    a=p.parse_args()
    directory=a.source_directory.resolve()
    output=a.output_directory.resolve()
    if output==directory or output in directory.parents:
        raise ValueError("Use an independent output namespace")
    result={}
    for role,records in DATA["records"].items():
        original=read_original(directory,records["parent"])
        text=transform(original,DATA["changes"][role])
        raw=text.encode("utf-8")
        expected=records["output"]
        if len(raw)!=expected["bytes"] or digest(raw)!=expected["sha256"]:
            raise ValueError("The complete generated source differs")
        if transform(text,DATA["changes"][role],reverse=True)!=original:
            raise ValueError("The reverse spans did not recover the whole original source")
        result[role]=text
    driver=read_original(directory,DATA["actual_driver"])
    start=driver.index("    preparation, reference_binding = actual_reference(args, paths)",
        driver.index("\ndef main():"))
    stop=driver.index("    restart = seed_report = None",start)
    constructor=driver[start:stop]
    own=result["input"]
    first=own.index("    preparation, reference_binding = actual_reference(args, paths)",
        own.index("\ndef _build_complete_original"))
    last=own.index("\n    return SimpleNamespace(q=q",first)
    if (own[first:last]!=constructor or digest(constructor.encode())!=DATA["constructor"]["sha256"]
            or len(constructor.encode())!=DATA["constructor"]["bytes"]):
        raise ValueError("The complete current constructor must remain exact original code")
    output.mkdir(parents=True,exist_ok=True)
    targets={role:output/DATA["records"][role]["output"]["name"] for role in result}
    if any(path.exists() for path in targets.values()):
        raise FileExistsError("Do not replace existing source outputs")
    for role,text in result.items():
        with targets[role].open("xb") as handle:
            handle.write(text.encode("utf-8"))
    print(json.dumps(dict(schema=DATA["schema"],complete_sources={
        role:dict(path=str(targets[role]),sha256=DATA["records"][role]["output"]["sha256"],
            bytes=DATA["records"][role]["output"]["bytes"]) for role in result},
        complete_source_text_forward_and_reverse=True,
        scientific_execution=False,AST_or_compile_executed=False,
        scientific_admission_precondition=False),sort_keys=True))


if __name__=="__main__":
    main()
